-- Database e-Rapor Kurikulum Merdeka (PHP Native)
-- Import lewat phpMyAdmin: menu Import, pilih file ini, klik Import.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS `e_rapor`;
CREATE DATABASE `e_rapor` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `e_rapor`;

CREATE TABLE `periode` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tahun_ajaran` VARCHAR(9) NOT NULL,
  `semester` TINYINT NOT NULL,
  `tgl_rapor` DATE NOT NULL,
  UNIQUE KEY `uq_periode` (`tahun_ajaran`, `semester`)
) ENGINE=InnoDB;

CREATE TABLE `pengaturan` (
  `id` TINYINT PRIMARY KEY,
  `nama_sekolah` VARCHAR(120) NOT NULL,
  `npsn` VARCHAR(12) NOT NULL DEFAULT '',
  `jenjang` ENUM('SD','SMP','SMA','SMK') NOT NULL DEFAULT 'SMP',
  `alamat` VARCHAR(200) NOT NULL DEFAULT '',
  `kelurahan` VARCHAR(60) NOT NULL DEFAULT '',
  `kecamatan` VARCHAR(60) NOT NULL DEFAULT '',
  `kabupaten` VARCHAR(60) NOT NULL DEFAULT '',
  `provinsi` VARCHAR(60) NOT NULL DEFAULT '',
  `kode_pos` VARCHAR(10) NOT NULL DEFAULT '',
  `telepon` VARCHAR(30) NOT NULL DEFAULT '',
  `email` VARCHAR(100) NOT NULL DEFAULT '',
  `website` VARCHAR(100) NOT NULL DEFAULT '',
  `kepala_sekolah` VARCHAR(100) NOT NULL DEFAULT '',
  `nip_kepsek` VARCHAR(25) NOT NULL DEFAULT '',
  `tempat_rapor` VARCHAR(60) NOT NULL DEFAULT '',
  `kktp` TINYINT NOT NULL DEFAULT 75,
  `bobot_tp` TINYINT NOT NULL DEFAULT 50,
  `periode_id` INT NOT NULL,
  `kunci_nilai` TINYINT(1) NOT NULL DEFAULT 0,
  `rapor_terbit` TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE `pengguna` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama` VARCHAR(100) NOT NULL,
  `nip` VARCHAR(25) NOT NULL DEFAULT '',
  `username` VARCHAR(40) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin','guru','kepsek') NOT NULL DEFAULT 'guru',
  `aktif` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL
) ENGINE=InnoDB;

CREATE TABLE `siswa` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nis` VARCHAR(20) NOT NULL UNIQUE,
  `nisn` VARCHAR(10) NOT NULL UNIQUE,
  `nama` VARCHAR(100) NOT NULL,
  `jk` ENUM('L','P') NOT NULL,
  `tempat_lahir` VARCHAR(60) NOT NULL DEFAULT '',
  `tgl_lahir` DATE NOT NULL,
  `agama` ENUM('Islam','Kristen','Katolik','Hindu','Buddha','Konghucu') NOT NULL DEFAULT 'Islam',
  `nama_ayah` VARCHAR(100) NOT NULL DEFAULT '',
  `nama_ibu` VARCHAR(100) NOT NULL DEFAULT '',
  `pekerjaan_ayah` VARCHAR(60) NOT NULL DEFAULT '',
  `pekerjaan_ibu` VARCHAR(60) NOT NULL DEFAULT '',
  `alamat` VARCHAR(200) NOT NULL DEFAULT '',
  `telepon_ortu` VARCHAR(20) NOT NULL DEFAULT '',
  `tgl_masuk` DATE NOT NULL,
  `status` ENUM('aktif','lulus','pindah') NOT NULL DEFAULT 'aktif'
) ENGINE=InnoDB;

CREATE TABLE `rombel` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `periode_id` INT NOT NULL,
  `nama` VARCHAR(20) NOT NULL,
  `tingkat` TINYINT NOT NULL,
  `fase` CHAR(1) NOT NULL DEFAULT 'D',
  `wali_id` INT DEFAULT NULL,
  UNIQUE KEY `uq_rombel` (`periode_id`, `nama`),
  FOREIGN KEY (`periode_id`) REFERENCES `periode`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`wali_id`) REFERENCES `pengguna`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

-- periode_id disalin agar satu siswa hanya bisa masuk satu rombel per periode (UNIQUE)
CREATE TABLE `anggota_rombel` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `rombel_id` INT NOT NULL,
  `periode_id` INT NOT NULL,
  `siswa_id` INT NOT NULL,
  UNIQUE KEY `uq_anggota` (`periode_id`, `siswa_id`),
  FOREIGN KEY (`rombel_id`) REFERENCES `rombel`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Mapel agama diisi kolom agama: hanya muncul di rapor siswa beragama sama
CREATE TABLE `mapel` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `kode` VARCHAR(12) NOT NULL UNIQUE,
  `nama` VARCHAR(100) NOT NULL,
  `kelompok` ENUM('umum','mulok') NOT NULL DEFAULT 'umum',
  `agama` VARCHAR(10) DEFAULT NULL,
  `urutan` TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE `pembelajaran` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `rombel_id` INT NOT NULL,
  `mapel_id` INT NOT NULL,
  `guru_id` INT DEFAULT NULL,
  `kktp` TINYINT DEFAULT NULL,
  UNIQUE KEY `uq_pembelajaran` (`rombel_id`, `mapel_id`),
  FOREIGN KEY (`rombel_id`) REFERENCES `rombel`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`mapel_id`) REFERENCES `mapel`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`guru_id`) REFERENCES `pengguna`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Tujuan Pembelajaran (TP) per pembelajaran; nilai per TP = sumatif lingkup materi
CREATE TABLE `tp` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `pembelajaran_id` INT NOT NULL,
  `kode` VARCHAR(10) NOT NULL,
  `deskripsi` VARCHAR(255) NOT NULL,
  FOREIGN KEY (`pembelajaran_id`) REFERENCES `pembelajaran`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `nilai_tp` (
  `tp_id` INT NOT NULL,
  `siswa_id` INT NOT NULL,
  `nilai` TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (`tp_id`, `siswa_id`),
  FOREIGN KEY (`tp_id`) REFERENCES `tp`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Sumatif akhir semester (SAS) + deskripsi manual opsional (menggantikan deskripsi otomatis)
CREATE TABLE `nilai_sas` (
  `pembelajaran_id` INT NOT NULL,
  `siswa_id` INT NOT NULL,
  `nilai` TINYINT UNSIGNED DEFAULT NULL,
  `deskripsi` TEXT DEFAULT NULL,
  PRIMARY KEY (`pembelajaran_id`, `siswa_id`),
  FOREIGN KEY (`pembelajaran_id`) REFERENCES `pembelajaran`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `ekskul` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama` VARCHAR(60) NOT NULL,
  `pembina` VARCHAR(100) NOT NULL DEFAULT '',
  `wajib` TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE `nilai_ekskul` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `periode_id` INT NOT NULL,
  `siswa_id` INT NOT NULL,
  `ekskul_id` INT NOT NULL,
  `predikat` ENUM('Sangat Baik','Baik','Cukup','Kurang') NOT NULL,
  `keterangan` VARCHAR(200) NOT NULL DEFAULT '',
  UNIQUE KEY `uq_ekskul` (`periode_id`, `siswa_id`, `ekskul_id`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`ekskul_id`) REFERENCES `ekskul`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Data rapor per siswa per periode: ketidakhadiran, catatan wali kelas, keputusan kenaikan
CREATE TABLE `rapor` (
  `periode_id` INT NOT NULL,
  `siswa_id` INT NOT NULL,
  `sakit` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `izin` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `alfa` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `catatan` TEXT DEFAULT NULL,
  `keputusan` ENUM('','naik','tidak_naik','lulus','tidak_lulus') NOT NULL DEFAULT '',
  PRIMARY KEY (`periode_id`, `siswa_id`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS = 1;

